const waiting = Boolean(run.pending?.request) || receipts.length > 0;
const stepNow = run.activeStep ? `${run.activeStep.phase.id}#${run.activeStep.index}` : "-";
useEffect(() => {
  if (waiting) setPane("now");
}, [waiting]);
useEffect(() => {
  setPane("now");
}, [stepNow]);

